Animal? animalById(String id) {
  for (final animal in livestockAnimals) {
    if (animal.id == id) return animal;
  }
  return null;
}

List<AnimalDisease> diseasesForAnimal(String animalId) =>
    livestockDiseases.where((d) => d.animalId == animalId).toList();
